namespace UniversityCourseCatalog.Models;

public class Department
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Code { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Instructor
{
    public int Id { get; set; }
    public string Name { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Email { get; set; } = string.Empty;
    public string Bio { get; set; } = string.Empty;
}

namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string Location { get; set; } = string.Empty;
    public int DepartmentId { get; set; }
    public int InstructorId { get; set; }
    public bool IsFeatured { get; set; }
}

using System.ComponentModel.DataAnnotations;

namespace UniversityCourseCatalog.Models;

public class EnrollmentRequest
{
    [Required(ErrorMessage = "Full name is required.")]
    [StringLength(100)]
    public string StudentName { get; set; } = string.Empty;

    [Required(ErrorMessage = "Student ID is required.")]
    [RegularExpression(@"^[A-Za-z0-9]{6,12}$", ErrorMessage = "Student ID must be 6–12 alphanumeric characters.")]
    public string StudentId { get; set; } = string.Empty;

    [Required(ErrorMessage = "Please select a course.")]
    [Range(1, int.MaxValue, ErrorMessage = "Please select a course.")]
    public int CourseId { get; set; }

    [EmailAddress(ErrorMessage = "Please enter a valid email address.")]
    [Required(ErrorMessage = "Email is required.")]
    public string Email { get; set; } = string.Empty;

    [StringLength(500)]
    public string? Notes { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Instructor> _instructors;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _instructors = new List<Instructor>
        {
            new() { Id = 1, Name = "Dr. Alice Chen", Title = "Professor of Computer Science", Email = "achen@university.edu", Bio = "Dr. Chen specializes in artificial intelligence and machine learning. She has published over 50 papers in top-tier conferences and holds three patents in natural language processing. She received her Ph.D. from MIT and has been teaching for 15 years." },
            new() { Id = 2, Name = "Dr. Robert Marsh", Title = "Associate Professor of Mathematics", Email = "rmarsh@university.edu", Bio = "Dr. Marsh focuses on applied mathematics and statistics. His research explores stochastic processes and their applications in finance. He is the recipient of the university's Outstanding Teaching Award." },
            new() { Id = 3, Name = "Dr. Elena Vasquez", Title = "Professor of Biology", Email = "evasquez@university.edu", Bio = "Dr. Vasquez is a molecular biologist with expertise in genetics and genomics. Her lab has made significant contributions to understanding gene expression in cancer cells." },
            new() { Id = 4, Name = "Dr. James Okoro", Title = "Lecturer in English", Email = "jokoro@university.edu", Bio = "Dr. Okoro is a published poet and literary critic with a focus on contemporary American fiction. He has authored two collections of poetry and a critical study of postmodern narrative." },
            new() { Id = 5, Name = "Dr. Sarah Kim", Title = "Associate Professor of Physics", Email = "skim@university.edu", Bio = "Dr. Kim researches quantum computing and condensed matter physics. She leads the university's Quantum Information Lab and has secured multiple NSF grants." },
            new() { Id = 6, Name = "Dr. Michael Torres", Title = "Professor of History", Email = "mtorres@university.edu", Bio = "Dr. Torres is a historian of Latin American politics and society. He has written extensively on 20th-century revolutionary movements and their lasting impact on modern governance." },
        };

        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, programming languages, and software systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Exploration of numbers, structures, patterns, and quantitative reasoning." },
            new() { Id = 3, Name = "Biology", Code = "BIO", Description = "Investigation of living organisms, their structure, function, and evolution." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Analysis of literature, language, writing, and communication." },
            new() { Id = 5, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 6, Name = "History", Code = "HIST", Description = "Examination of past events, civilizations, and their influence on the present." },
        };

        _courses = new List<Course>
        {
            // Computer Science
            new() { Id = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, data structures, and file I/O. No prior experience required.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", Location = "Science Hall 201", DepartmentId = 1, InstructorId = 1, IsFeatured = true },
            new() { Id = 2, Code = "CS 201", Title = "Data Structures & Algorithms", Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs, hash tables) and algorithm design techniques including sorting, searching, and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:00–11:20 AM", Location = "Science Hall 305", DepartmentId = 1, InstructorId = 1 },
            new() { Id = 3, Code = "CS 350", Title = "Artificial Intelligence", Description = "Introduction to AI concepts including search algorithms, knowledge representation, machine learning, neural networks, and natural language processing.", Credits = 3, Schedule = "Mon/Wed 2:00–3:20 PM", Location = "Tech Building 110", DepartmentId = 1, InstructorId = 1, IsFeatured = true },

            // Mathematics
            new() { Id = 4, Code = "MATH 101", Title = "Calculus I", Description = "Introduction to differential calculus: limits, continuity, derivatives of algebraic and trigonometric functions, and applications of derivatives.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 2 },
            new() { Id = 5, Code = "MATH 201", Title = "Linear Algebra", Description = "Study of vector spaces, linear transformations, matrices, determinants, eigenvalues, and applications to systems of linear equations.", Credits = 3, Schedule = "Tue/Thu 1:00–2:20 PM", Location = "Math Building 205", DepartmentId = 2, InstructorId = 2, IsFeatured = true },
            new() { Id = 6, Code = "MATH 310", Title = "Probability & Statistics", Description = "Fundamentals of probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", Location = "Math Building 101", DepartmentId = 2, InstructorId = 2 },

            // Biology
            new() { Id = 7, Code = "BIO 101", Title = "General Biology", Description = "Survey of biological principles including cell biology, genetics, evolution, ecology, and organismal diversity. Includes weekly laboratory sessions.", Credits = 4, Schedule = "Tue/Thu 9:00–10:20 AM", Location = "Life Sciences 150", DepartmentId = 3, InstructorId = 3, IsFeatured = true },
            new() { Id = 8, Code = "BIO 240", Title = "Genetics", Description = "Principles of heredity, gene structure and function, chromosomal mechanisms, and population genetics. Prerequisite: BIO 101.", Credits = 3, Schedule = "Mon/Wed 10:00–11:20 AM", Location = "Life Sciences 220", DepartmentId = 3, InstructorId = 3 },

            // English
            new() { Id = 9, Code = "ENG 101", Title = "Composition & Rhetoric", Description = "Development of critical reading, analytical writing, and argumentation skills through essays and research-based assignments.", Credits = 3, Schedule = "Mon/Wed/Fri 1:00–1:50 PM", Location = "Humanities 310", DepartmentId = 4, InstructorId = 4 },
            new() { Id = 10, Code = "ENG 250", Title = "American Literature", Description = "Survey of American literary works from the colonial period through the 21st century, exploring themes of identity, freedom, and social change.", Credits = 3, Schedule = "Tue/Thu 2:00–3:20 PM", Location = "Humanities 215", DepartmentId = 4, InstructorId = 4, IsFeatured = true },

            // Physics
            new() { Id = 11, Code = "PHYS 101", Title = "General Physics I", Description = "Introduction to classical mechanics: kinematics, Newton's laws, energy, momentum, rotational motion, and oscillations. Calculus-based.", Credits = 4, Schedule = "Mon/Wed/Fri 8:00–8:50 AM", Location = "Physics Lab 100", DepartmentId = 5, InstructorId = 5 },
            new() { Id = 12, Code = "PHYS 305", Title = "Quantum Mechanics", Description = "Foundational concepts of quantum theory including wave-particle duality, the Schrödinger equation, quantum states, and measurement theory.", Credits = 3, Schedule = "Tue/Thu 11:00 AM–12:20 PM", Location = "Physics Lab 300", DepartmentId = 5, InstructorId = 5, IsFeatured = true },

            // History
            new() { Id = 13, Code = "HIST 101", Title = "World History to 1500", Description = "Survey of major civilizations, empires, and cultural developments from prehistory through the late medieval period.", Credits = 3, Schedule = "Mon/Wed/Fri 2:00–2:50 PM", Location = "Social Sciences 105", DepartmentId = 6, InstructorId = 6 },
            new() { Id = 14, Code = "HIST 275", Title = "Modern Latin America", Description = "Exploration of Latin American history from independence movements through contemporary political and social transformations.", Credits = 3, Schedule = "Tue/Thu 3:30–4:50 PM", Location = "Social Sciences 210", DepartmentId = 6, InstructorId = 6 },
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Instructor> GetInstructors() => _instructors;

    public Instructor? GetInstructor(int id) => _instructors.FirstOrDefault(i => i.Id == id);

    public List<Course> GetCourses() => _courses;

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public List<Course> GetCoursesByDepartment(int departmentId) =>
        _courses.Where(c => c.DepartmentId == departmentId).ToList();

    public List<Course> SearchCourses(string? query, int? departmentId)
    {
        var results = _courses.AsEnumerable();

        if (departmentId.HasValue && departmentId.Value > 0)
            results = results.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(query))
        {
            var q = query.Trim().ToLowerInvariant();
            results = results.Where(c =>
                c.Title.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(q, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(q, StringComparison.OrdinalIgnoreCase));
        }

        return results.ToList();
    }

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

