            new() { Id = 5, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 6, Name = "History", Code = "HIST", Description = "Examination of past events, civilizations, and their influence on the present." },
