@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService Catalog

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Complete the form below to submit an enrollment request. You will be notified by email once your request has been reviewed.</p>

@if (submitted)
{
    <div class="alert alert-success">
        <h4 class="alert-heading">Request Submitted!</h4>
        <p>Thank you, <strong>@model.StudentName</strong>. Your enrollment request for <strong>@selectedCourseTitle</strong> has been received.</p>
        <p>A confirmation will be sent to <strong>@model.Email</strong>.</p>
        <hr />
        <a href="enroll" class="btn btn-outline-success">Submit Another Request</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-8 col-lg-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentName" name="model.StudentName" value="@model.StudentName" required maxlength="100" />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID <span class="text-danger">*</span></label>
                    <input type="text" class="form-control" id="studentId" name="model.StudentId" value="@model.StudentId" required pattern="[A-Za-z0-9]{6,12}" title="6–12 alphanumeric characters" />
                </div>

                <div class="mb-3">
                    <label for="email" class="form-label">Email <span class="text-danger">*</span></label>
                    <input type="email" class="form-control" id="email" name="model.Email" value="@model.Email" required />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course <span class="text-danger">*</span></label>
                    <select class="form-select" id="courseId" name="model.CourseId" required>
                        <option value="">— Select a course —</option>
                        @foreach (var course in courses)
                        {
                            var dept = Catalog.GetDepartment(course.DepartmentId);
